class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        n = len(strs[0])
        dp = [1] * n
        for i in range(1, n):
            for j in range(i):
                valid = True
                for a in strs:
                    if a[j] > a[i]: 
                        valid = False
                        break
                if valid:
                    dp[i] = max(dp[i], dp[j] + 1)
        return n - max(dp)

class Solution(object):
    def leastOpsExpressTarget(self, x, target):
        return self.cost(x, target)

    def cost(self, x, val):
        if val == x:
            return 0
        elif val < x:
            # two possible states
            # either val > x / 2: we substract 1s
            state_1 = 2 * (x - val)
            # or val < x / 2: we divide once to 1 and we add enough 1s
            state_2 = 2*val - 1
            return min(state_1, state_2)
        else:
            # there is a maximum power of x that we can add
            p = int(log(val) // log(x))
            # and either x^p or x^(p+1) is the closest
            a = x**p
            b = a*x
            if b < 2*val:
                # x**(p+1) - val < val - x**p
                return min(p + self.cost(x, val - a), p + 1 + self.cost(x, b - val))
            else:
                return p + self.cost(x, val - a)

class Solution:
    def mergeStones(self, stones, K):
        if (len(stones)-1) % (K-1):
            return -1
        prefix = [0]
        for x in stones:
            prefix.append(prefix[-1]+x)
        dp = [[0]*len(stones) for _ in range(len(stones))]
        for l in range(K-1, len(stones)):
            for i in range(len(stones)-l):
                dp[i][i+l] = min(dp[i][j]+dp[j+1][i+l] for j in range(i, i+l, K-1))
                if l % (K-1) == 0:
                    dp[i][i+l] += prefix[i+l+1] - prefix[i]
        return dp[0][len(stones)-1]
